/* Mark-scheme language flashcards: the precise wording that earns the mark.
   Written for this site from the specification content (not copied from Pearson mark schemes).
   [unit, front, back] */
const KEY_PHRASES_RAW = [
 /* ---------- Physics ---------- */
 ['WPH11','Define a vector quantity.','A quantity with both magnitude and direction.'],
 ['WPH11','State Newton’s first law.','An object stays at rest or moves with constant velocity unless a resultant force acts on it.'],
 ['WPH11','State Newton’s third law.','If body A exerts a force on body B, B exerts an equal and opposite force on A, of the same type.'],
 ['WPH11','What does the area under a velocity–time graph give?','The displacement.'],
 ['WPH11','State the principle of conservation of momentum.','In a closed system (no external forces), total momentum before = total momentum after.'],
 ['WPH11','Define the moment of a force.','Force × perpendicular distance from the pivot to the line of action of the force.'],
 ['WPH11','State the principle of moments.','For equilibrium, sum of clockwise moments = sum of anticlockwise moments about any point.'],
 ['WPH11','Why does an object reach terminal velocity?','Drag increases with speed until drag (+ upthrust) equals weight, so the resultant force is zero and acceleration is zero.'],
 ['WPH11','State Hooke’s law.','Extension is directly proportional to force applied, up to the limit of proportionality.'],
 ['WPH11','Define the Young modulus.','Stress ÷ strain (in the region where Hooke’s law applies).'],
 ['WPH11','What is the difference between elastic and plastic deformation?','Elastic: the material returns to its original shape when the force is removed. Plastic: it is permanently deformed.'],
 ['WPH11','Define upthrust.','Upthrust = weight of fluid displaced.'],
 ['WPH11','Laminar vs turbulent flow?','Laminar: layers of fluid don’t cross, velocity at a point is constant. Turbulent: eddies and mixing, velocity changes.'],
 ['WPH12','Define electric current.','The rate of flow of charge.'],
 ['WPH12','Define potential difference.','Energy transferred per unit charge ($W/Q$) between two points.'],
 ['WPH12','State Ohm’s law.','Current is directly proportional to p.d. for a conductor at constant temperature.'],
 ['WPH12','Why does a filament lamp’s resistance increase with current?','The filament gets hotter, so lattice ions vibrate more and electrons collide with them more often.'],
 ['WPH12','Why does an NTC thermistor’s resistance fall as temperature rises?','More charge carriers are released, increasing n (this outweighs increased lattice vibrations).'],
 ['WPH12','Define e.m.f.','Energy transferred to electrical energy per unit charge by the source.'],
 ['WPH12','Why is terminal p.d. less than e.m.f. when current flows?','Some energy per unit charge is transferred in the internal resistance (“lost volts” = Ir).'],
 ['WPH12','Define a progressive wave.','A wave that transfers energy from one place to another without transferring material.'],
 ['WPH12','What does “coherent” mean?','Constant phase difference and the same frequency.'],
 ['WPH12','How does a stationary wave form?','Two waves of the same frequency travelling in opposite directions superpose (e.g. a wave reflected back on itself).'],
 ['WPH12','What is a node?','A point of zero amplitude, where waves always meet in antiphase (destructive interference).'],
 ['WPH12','State the photoelectric threshold idea.','Each electron absorbs one photon; it is emitted only if photon energy hf ≥ work function, however intense the light.'],
 ['WPH12','Define the work function.','The minimum energy needed to remove an electron from the surface of a metal.'],
 ['WPH12','Why do line spectra show discrete frequencies?','Electrons move between discrete energy levels, emitting photons of energy equal to the difference, so only certain frequencies.'],
 ['WPH12','What does electron diffraction show?','Electrons behave as waves (wave–particle duality), with $\\lambda = \\frac{h}{p}$.'],
 ['WPH13','What is a systematic error?','An error that shifts every reading by the same amount in the same direction (e.g. zero error).'],
 ['WPH13','What is a random error and how do you reduce its effect?','Unpredictable scatter in readings; repeat and calculate a mean.'],
 ['WPH13','How do you reduce parallax error?','Read the scale at eye level, perpendicular to the scale.'],
 ['WPH13','Why measure a diameter at several places and orientations?','The wire or ball may not be uniform/circular, so take a mean.'],
 ['WPH13','What makes a result “accurate”?','It is close to the true value.'],
 ['WPH13','What makes results “precise”?','Repeated readings are close to each other (little spread).'],
 ['WPH14','Define impulse.','Force × time, equal to the change in momentum.'],
 ['WPH14','What is conserved in an elastic collision?','Both momentum and kinetic energy.'],
 ['WPH14','Why does an object moving in a circle at constant speed accelerate?','Its direction (and so velocity) changes continuously; the resultant force acts towards the centre.'],
 ['WPH14','Define electric field strength.','Force per unit positive charge.'],
 ['WPH14','Define capacitance.','Charge stored per unit p.d. ($C = \\frac{Q}{V}$).'],
 ['WPH14','Define the time constant RC.','The time for the charge (or p.d., current) to fall to $\\frac{1}{e}$ (37%) of its initial value during discharge.'],
 ['WPH14','State Faraday’s law.','The induced e.m.f. is proportional to the rate of change of flux linkage.'],
 ['WPH14','State Lenz’s law.','The induced e.m.f. (current) acts to oppose the change that produced it.'],
 ['WPH14','Why are particles accelerated to high energies in colliders?','Higher energy gives shorter de Broglie wavelength to probe small structures, and enough energy to create massive particles ($E = mc^{2}$).'],
 ['WPH14','What did alpha scattering show?','Most of the atom is empty space; mass and positive charge are concentrated in a tiny nucleus.'],
 ['WPH14','What is conserved in particle interactions?','Charge, baryon number, lepton number (and energy/momentum).'],
 ['WPH15','Define specific heat capacity.','Energy needed to raise the temperature of 1 kg of a substance by 1 K.'],
 ['WPH15','Define specific latent heat.','Energy needed to change the state of 1 kg of a substance without a change in temperature.'],
 ['WPH15','What is internal energy?','The sum of the random kinetic and potential energies of the molecules.'],
 ['WPH15','What is absolute zero?','The temperature at which the molecules have minimum kinetic energy (internal energy is a minimum).'],
 ['WPH15','State two assumptions of the kinetic theory of gases.','Collisions are elastic; molecules have negligible volume; no forces between molecules except in collisions; random motion.'],
 ['WPH15','Define activity.','The number of nuclei decaying per second (rate of decay).'],
 ['WPH15','Define half-life.','The average time for half the undecayed nuclei of an isotope to decay.'],
 ['WPH15','Why is radioactive decay described as random and spontaneous?','Random: you can’t predict which nucleus decays next. Spontaneous: not affected by external factors (e.g. temperature).'],
 ['WPH15','Define binding energy.','The energy needed to separate a nucleus into its individual nucleons.'],
 ['WPH15','Why does fusion need very high temperatures?','Nuclei need very high kinetic energy to overcome electrostatic repulsion and get close enough for the strong force to act.'],
 ['WPH15','Define simple harmonic motion.','Acceleration is proportional to displacement from equilibrium and directed towards the equilibrium position.'],
 ['WPH15','What is resonance?','When the driving frequency equals the natural frequency, amplitude becomes a maximum.'],
 ['WPH15','What is a standard candle?','An object of known luminosity; measure its intensity to find distance using $I = \\frac{L}{4\\pi d^{2}}$.'],
 ['WPH15','State Newton’s law of gravitation.','The force between two point masses is proportional to the product of the masses and inversely proportional to the square of their separation.'],
 ['WPH16','How should you label a log graph axis?','ln (quantity / unit), e.g. ln (V / V).'],
 ['WPH16','Why use a fiducial marker when timing oscillations?','To mark a fixed reference point (at the equilibrium position, where the object moves fastest) so you start/stop timing consistently.'],
 ['WPH16','How do you find the percentage uncertainty of a value raised to a power?','Multiply the percentage uncertainty by the power.'],
 /* ---------- Chemistry ---------- */
 ['WCH11','Define relative atomic mass.','The weighted mean mass of an atom of an element relative to $\\frac{1}{12}$ the mass of an atom of carbon-12.'],
 ['WCH11','Define first ionisation energy.','Energy needed to remove one electron from each atom in one mole of gaseous atoms, forming one mole of gaseous 1+ ions.'],
 ['WCH11','Why does ionisation energy generally increase across a period?','Nuclear charge increases while shielding stays similar, so the outer electron is held more strongly.'],
 ['WCH11','Define an ionic bond.','Electrostatic attraction between oppositely charged ions.'],
 ['WCH11','Define a covalent bond.','Electrostatic attraction between two nuclei and a shared pair of electrons.'],
 ['WCH11','Define a dative covalent bond.','A covalent bond in which both shared electrons come from the same atom.'],
 ['WCH11','Describe metallic bonding.','Electrostatic attraction between positive metal ions and delocalised electrons.'],
 ['WCH11','Define electronegativity.','The ability of an atom to attract the bonding pair of electrons in a covalent bond.'],
 ['WCH11','Why do electron pairs determine molecular shape?','Electron pairs repel each other and arrange themselves as far apart as possible; lone pairs repel more than bonding pairs.'],
 ['WCH11','What is a nucleophile?','A species with a lone pair of electrons that it donates to form a new covalent bond.'],
 ['WCH11','What is an electrophile?','A species that accepts a pair of electrons.'],
 ['WCH11','Why can alkenes show E/Z isomerism?','Restricted rotation about the $\\ce{C=C}$ double bond, and each carbon of the double bond has two different groups attached.'],
 ['WCH11','What is a homologous series?','Compounds with the same general formula and functional group, differing by $\\ce{CH2}$, with similar chemical properties.'],
 ['WCH12','Define standard enthalpy change of formation.','Enthalpy change when one mole of a compound is formed from its elements in their standard states under standard conditions.'],
 ['WCH12','Define standard enthalpy change of combustion.','Enthalpy change when one mole of a substance is completely burned in oxygen under standard conditions.'],
 ['WCH12','State Hess’s law.','The enthalpy change of a reaction is independent of the route taken.'],
 ['WCH12','Define activation energy.','The minimum energy colliding particles need for a reaction to occur.'],
 ['WCH12','Why does increasing temperature increase rate?','More particles have energy ≥ Ea, so a greater proportion of collisions are successful (and collisions are more frequent).'],
 ['WCH12','How does a catalyst work?','It provides an alternative reaction pathway with a lower activation energy.'],
 ['WCH12','State Le Chatelier’s principle.','If a system at equilibrium is changed, the position of equilibrium shifts to oppose the change.'],
 ['WCH12','What is a dynamic equilibrium?','Forward and reverse rates are equal, so concentrations stay constant, in a closed system.'],
 ['WCH12','Define oxidation and reduction (electrons).','Oxidation is loss of electrons; reduction is gain of electrons.'],
 ['WCH12','What causes hydrogen bonding?','A hydrogen atom bonded to N, O or F is attracted to a lone pair on an N, O or F of another molecule.'],
 ['WCH12','Why do London forces increase with chain length?','More electrons, so larger instantaneous and induced dipoles.'],
 ['WCH12','Why does reactivity of Group 2 metals increase down the group?','Outer electrons are further from the nucleus and more shielded, so are lost more easily (lower ionisation energy).'],
 ['WCH12','Why does the oxidising power of halogens decrease down the group?','Atoms get bigger and more shielded, so they attract an extra electron less strongly.'],
 ['WCH12','What does an infrared spectrum show?','Bonds absorb IR at characteristic wavenumbers, identifying functional groups (e.g. broad O–H, $\\ce{C=O}$ near 1700 cm⁻¹).'],
 ['WCH13','How do you know a titration end point has been reached?','The first permanent colour change of the indicator.'],
 ['WCH13','Why rinse a burette with the solution it will contain?','So the solution isn’t diluted by water left in the burette.'],
 ['WCH13','What are concordant titres?','Titres within 0.10 cm³ of each other.'],
 ['WCH13','Why is a water bath used rather than a Bunsen to heat organic liquids?','Organic liquids are flammable, and a water bath gives even, controlled heating.'],
 ['WCH13','What is the purpose of anti-bumping granules?','To give smooth boiling (prevent large bubbles forming).'],
 ['WCH13','Why is reflux used?','To heat a reaction mixture for a long time without losing volatile reactants or products.'],
 ['WCH14','Define order of reaction with respect to a reactant.','The power to which its concentration is raised in the rate equation.'],
 ['WCH14','What is the rate-determining step?','The slowest step in the mechanism; species in it appear in the rate equation.'],
 ['WCH14','Define entropy.','A measure of the number of ways particles and energy can be arranged (disorder).'],
 ['WCH14','When is a reaction thermodynamically feasible?','When $\\Delta G \\le 0$ (equivalently, $\\Delta S_{\\text{total}} \\ge 0$).'],
 ['WCH14','Define lattice energy (formation).','Enthalpy change when one mole of an ionic solid is formed from its gaseous ions under standard conditions.'],
 ['WCH14','Define a Brønsted–Lowry acid.','A proton ($\\ce{H^{+}}$) donor.'],
 ['WCH14','What is a buffer?','A solution that minimises pH changes when small amounts of acid or base are added.'],
 ['WCH14','Define a strong acid.','An acid that fully dissociates in water.'],
 ['WCH14','How does a buffer resist added acid (ethanoic acid / ethanoate)?','Added $\\ce{H+}$ reacts with the large reservoir of $\\ce{CH3COO-}$ to form $\\ce{CH3COOH}$, so $[\\ce{H+}]$ barely changes.'],
 ['WCH14','Why do optical isomers exist?','A chiral carbon with four different groups gives non-superimposable mirror images.'],
 ['WCH14','How does a racemic mixture form in nucleophilic addition to a carbonyl?','The planar $\\ce{C=O}$ can be attacked equally from either side, giving equal amounts of each enantiomer.'],
 ['WCH14','What does a split NMR peak ($n + 1$ rule) tell you?','A peak split into $n + 1$ lines shows n hydrogens on the adjacent carbon(s).'],
 ['WCH15','Define standard electrode potential.','The e.m.f. of a half-cell compared with the standard hydrogen electrode under standard conditions (298 K, 100 kPa, 1 mol dm⁻³).'],
 ['WCH15','What is the role of a salt bridge?','To complete the circuit by allowing ions to move between half-cells, without the solutions mixing.'],
 ['WCH15','Define a transition metal.','An element that forms at least one stable ion with a partially filled d sub-shell.'],
 ['WCH15','What is a ligand?','A species with a lone pair that forms a dative covalent bond to a central metal ion.'],
 ['WCH15','Why are transition metal complexes coloured?','Ligands split the d orbitals; electrons absorb certain frequencies of visible light to jump between them, and the complementary colour is seen.'],
 ['WCH15','Why are transition metals good catalysts?','They have variable oxidation states and can adsorb reactants onto their surface.'],
 ['WCH15','Why is benzene more stable than expected for cyclohexatriene?','Its $\\pi$ electrons are delocalised over the ring.'],
 ['WCH15','Why does benzene undergo substitution rather than addition?','Substitution keeps the stable delocalised $\\pi$ system.'],
 ['WCH15','Why is phenylamine a weaker base than ammonia?','The nitrogen lone pair is partly delocalised into the ring, so it is less available to accept a proton.'],
 ['WCH15','Conditions for making a diazonium salt?','Phenylamine with sodium nitrite and hydrochloric acid, below 10 °C.'],
 ['WCH15','What is a condensation polymer?','A polymer formed by joining monomers with loss of a small molecule such as water or $\\ce{HCl}$.'],
 ['WCH16','Why do impurities affect a melting point?','They lower the melting point and make it melt over a wider range.'],
 ['WCH16','How do you recrystallise a solid?','Dissolve in minimum hot solvent, filter hot, cool to crystallise, filter under reduced pressure, wash with cold solvent, dry.'],
 ['WCH16','Why add starch near the end of an iodine–thiosulfate titration?','Starch gives a sharp blue-black to colourless end point; added too early it binds iodine irreversibly.'],
 ['WCH16','Why is no indicator needed in manganate(VII) titrations?','$\\ce{MnO4^{-}}$ is purple and its reduced form is almost colourless, so the first permanent pink shows the end point.'],
 /* ---------- Biology ---------- */
 ['WBI11','Why is water a good solvent?','It is polar, so ions and polar molecules dissolve in it (they are attracted to the $\\delta+$ and $\\delta-$ regions).'],
 ['WBI11','How is a glycosidic bond formed?','By a condensation reaction between two monosaccharides, releasing water.'],
 ['WBI11','Why is starch a good storage molecule?','Insoluble (no osmotic effect), compact (coiled/branched), and easily hydrolysed to glucose.'],
 ['WBI11','Why does an enzyme only catalyse one reaction?','Its active site has a specific shape that is complementary to one substrate.'],
 ['WBI11','What happens when an enzyme is denatured?','Bonds holding the tertiary structure break, so the active site changes shape and is no longer complementary to the substrate.'],
 ['WBI11','How does an enzyme lower activation energy?','By forming enzyme–substrate complexes that put strain on bonds or bring reactants together.'],
 ['WBI11','What is meant by semi-conservative replication?','Each new DNA molecule contains one original strand and one newly synthesised strand.'],
 ['WBI11','What does DNA polymerase do?','Joins adjacent nucleotides by forming phosphodiester bonds (condensation reactions).'],
 ['WBI11','Why is the genetic code described as degenerate?','More than one triplet codes for the same amino acid.'],
 ['WBI11','Why does atherosclerosis increase the risk of a blood clot?','Damage to the endothelium and plaque formation; if a plaque ruptures, a clotting cascade forms a thrombus.'],
 ['WBI11','State the role of thrombin.','Converts soluble fibrinogen into insoluble fibrin.'],
 ['WBI11','Why does a single-celled organism not need a mass transport system?','It has a large surface area to volume ratio, so diffusion is fast enough over short distances.'],
 ['WBI11','Define osmosis.','Net movement of water molecules from a less concentrated (higher water potential) solution to a more concentrated one across a partially permeable membrane.'],
 ['WBI11','Define active transport.','Movement of molecules against a concentration gradient using ATP and carrier proteins.'],
 ['WBI11','Define facilitated diffusion.','Passive movement down a concentration gradient through channel or carrier proteins.'],
 ['WBI12','Define magnification and resolution.','Magnification: how many times bigger the image is than the object. Resolution: the ability to distinguish two points as separate.'],
 ['WBI12','Why are prokaryotes different from eukaryotes?','Prokaryotes have no nucleus or membrane-bound organelles, have 70S ribosomes and circular DNA.'],
 ['WBI12','What is meant by a totipotent stem cell?','A cell that can differentiate into any cell type, including extra-embryonic cells.'],
 ['WBI12','Why are gametes haploid?','So that the diploid number is restored at fertilisation.'],
 ['WBI12','How does meiosis produce genetic variation?','Independent assortment of homologous chromosomes and crossing over between chromatids.'],
 ['WBI12','How does cellulose give strength to cell walls?','Straight chains of $\\beta$-glucose; hydrogen bonds between adjacent chains form microfibrils.'],
 ['WBI12','Define a species (biological).','A group of organisms that can interbreed to produce fertile offspring.'],
 ['WBI12','What is genetic diversity?','The number of different alleles of genes in a population.'],
 ['WBI12','Define natural selection.','Individuals with advantageous alleles are more likely to survive and reproduce, so pass on those alleles; allele frequency increases.'],
 ['WBI13','Why is a control included in an experiment?','To show that the effect is due to the independent variable only.'],
 ['WBI13','How should tables be laid out?','Independent variable in the first column, units in the column headings (not in cells), consistent decimal places.'],
 ['WBI13','What does standard deviation show?','The spread of the data around the mean.'],
 ['WBI13','What do overlapping error bars (SD) suggest?','The difference between means may not be significant.'],
 ['WBI14','What is a trophic level?','The position of an organism in a food chain.'],
 ['WBI14','Why is energy transfer between trophic levels inefficient?','Energy is lost as heat in respiration, in undigested material/faeces, and parts not eaten.'],
 ['WBI14','Define net primary productivity.','GPP minus energy used in plant respiration; the energy available to the next trophic level.'],
 ['WBI11','How does a stop codon end translation?','No tRNA has an anticodon for it, so the polypeptide is released.'],
 ['WBI14','How do antibiotics work?','They are chemicals that kill bacteria or stop their growth (e.g. inhibit cell wall synthesis); they do not affect viruses.'],
 ['WBI14','How does antibiotic resistance spread?','A mutation gives resistance; resistant bacteria survive and reproduce; allele frequency increases (natural selection).'],
 ['WBI14','Describe the role of T helper cells.','Bind to antigens on antigen-presenting cells and release cytokines that activate B cells and T killer cells.'],
 ['WBI14','How do memory cells give long-term immunity?','On re-infection they rapidly divide, so antibodies are made faster and in larger amounts (secondary response).'],
 ['WBI14','What is the role of the light-dependent reactions?','Produce ATP and reduced NADP using light energy, splitting water (photolysis) to release oxygen.'],
 ['WBI14','What is the role of RuBisCO?','Catalyses fixation of $\\ce{CO2}$ with RuBP in the Calvin cycle.'],
 ['WBI14','Why is the climate change evidence debated?','Data may be extrapolated, correlation is not causation, and sources may be biased.'],
 ['WBI15','What is the role of oxygen in aerobic respiration?','It is the final electron acceptor in the electron transport chain, combining with electrons and $\\ce{H^{+}}$ to form water.'],
 ['WBI15','Why is less ATP made in anaerobic respiration?','Only glycolysis runs, as no oxygen accepts electrons so the Krebs cycle and ETC stop.'],
 ['WBI15','How is a resting potential maintained?','The $\\ce{Na+}$/$\\ce{K+}$ pump moves 3 $\\ce{Na+}$ out and 2 $\\ce{K+}$ in; the membrane is more permeable to $\\ce{K+}$, which diffuses out.'],
 ['WBI15','What happens during depolarisation?','Voltage-gated $\\ce{Na^{+}}$ channels open; $\\ce{Na^{+}}$ diffuses in, making the inside more positive.'],
 ['WBI15','Why does a nerve impulse travel in one direction?','The membrane behind is in its refractory period, so it can’t be depolarised again.'],
 ['WBI15','How does myelination speed up conduction?','Depolarisation only occurs at nodes of Ranvier, so the impulse jumps between them (saltatory conduction).'],
 ['WBI15','Describe the sliding filament theory.','Myosin heads bind to actin, form cross-bridges and pull actin filaments towards the centre of the sarcomere, using ATP.'],
 ['WBI15','What is the role of calcium ions in muscle contraction?','They bind to troponin, moving tropomyosin to expose myosin binding sites on actin.'],
 ['WBI15','What is homeostasis?','Maintaining a constant internal environment within narrow limits, using negative feedback.'],
 ['WBI15','How do steroid hormones act on cells?','They are lipid-soluble, diffuse through the membrane, bind to receptors and act as transcription factors for target genes.'],
 ['WBI15','Define habituation.','A reduced response to a repeated, harmless stimulus.'],
 ['WBI16','Why use a buffer in an enzyme investigation?','To keep pH constant, so pH is not a variable affecting the enzyme.'],
 ['WBI16','What does a significant result in a statistical test mean?','The probability that the difference/correlation is due to chance is less than 5% ($p < 0.05$), so reject the null hypothesis.'],
 ['WBI16','How should you describe controlling temperature precisely?','Use a thermostatically controlled water bath at a stated temperature (e.g. 25 °C), checked with a thermometer.'],
 /* ---------- Maths ---------- */
 ['WST02','How should a hypothesis-test conclusion be written?','In context and non-assertively, e.g. “There is (insufficient) evidence that the mean time has increased.”'],
 ['WST01','What does the product moment correlation coefficient measure?','The strength of the linear relationship between two variables.'],
 ['WST01','When are two events independent?','P(A ∩ B) = P(A) × P(B).'],
 ['WST01','When are two events mutually exclusive?','They cannot happen at the same time: P(A ∩ B) = 0.'],
 ['WST02','Conditions for a binomial model?','Fixed number of trials, two outcomes, constant probability of success, independent trials.'],
 ['WST02','Conditions for a Poisson model?','Events occur singly, independently, randomly, at a constant average rate.'],
 ['WST02','Define a critical region.','The range of values of the test statistic that would lead to rejecting $H_{0}$.'],
 ['WST03','What does the central limit theorem say?','For large n, the sample mean is approximately normally distributed, whatever the population’s distribution.'],
 ['WME01','What does modelling an object as a particle mean?','Its dimensions are negligible, so rotation and air resistance can be ignored and mass acts at a point.'],
 ['WME01','What does “light, inextensible string” mean?','Light: mass negligible, so tension is the same throughout. Inextensible: connected particles have the same acceleration.'],
 ['WME01','What does “smooth” surface or pulley mean?','No friction acts (tension the same on both sides of a smooth pulley).'],
 ['WME01','What does modelling a rod as uniform mean?','Its mass acts at its midpoint.'],
 ['WME02','State the work–energy principle.','Work done by non-conservative forces = change in total mechanical energy (KE + PE).'],
 /* ---------- Economics ---------- */
 ['WEC11','What does “define” need, and how many marks does it usually earn?','A precise meaning of the term in one sentence: usually 1 knowledge mark. Add an example from the data for the application mark.'],
 ['WEC11','“Explain” questions in Section B: what earns full marks?','Knowledge (definition), application (use the context or data), and analysis (a linked chain of cause and effect). A diagram can carry the analysis.'],
 ['WEC11','Define opportunity cost.','The value of the next best alternative given up when a choice is made.'],
 ['WEC11','Define price elasticity of demand.','The responsiveness of quantity demanded to a change in price: % change in Qd ÷ % change in P.'],
 ['WEC11','Define a negative externality.','A cost to a third party not involved in the transaction, so social cost is greater than private cost.'],
 ['WEC11','Define market failure.','When the free market allocates resources inefficiently, so welfare is not maximised (e.g. externalities, public goods, information gaps).'],
 ['WEC11','Specific vs ad valorem tax on a diagram?','Specific (a fixed amount per unit): supply shifts up in parallel. Ad valorem (a percentage): supply pivots, so the gap widens as price rises.'],
 ['WEC11','What does “evaluate” or “assess” need?','A judgement backed by developed counter-arguments: magnitude, time period, stakeholders, or what it depends on.'],
 ['WEC12','Define aggregate demand.','Total planned spending on goods and services in an economy at a given price level: $\\mathrm{AD} = C + I + G + (X - M)$.'],
 ['WEC12','Define the multiplier effect.','An initial injection leads to a larger final increase in national income, because spending becomes someone else’s income.'],
 ['WEC12','Define real GDP.','The value of output adjusted for inflation, measured at constant prices.'],
 ['WEC12','Define inflation.','A sustained increase in the general price level, measured by changes in a price index (e.g. CPI).'],
 ['WEC12','Demand-side vs supply-side policy?','Demand-side (fiscal or monetary) shifts AD; supply-side policies increase productive capacity, shifting LRAS right.'],
 ['WEC12','How many marks are for evaluation in the 20-mark essay, and what counts?','8 marks: developed points linked to the context, ending in a reasoned judgement.'],
 ['WEC12','4- and 6-mark questions: evaluate or not?','No. They are knowledge, application and analysis only, so put your evaluation time into the longer questions.'],
 ['WEC13','Define contestability.','How easily firms can enter or leave a market, depending on barriers to entry and sunk costs.'],
 ['WEC13','Profit-maximising output rule?','Produce where marginal cost = marginal revenue (MC = MR).'],
 ['WEC13','Define allocative efficiency.','When price = marginal cost ($P = \\mathrm{MC}$), so resources match consumers’ preferences.'],
 ['WEC13','Define productive efficiency.','Producing at the lowest point of the average cost curve (where MC = AC).'],
 ['WEC13','Define economies of scale.','Falling long-run average costs as output increases (e.g. buying inputs in bulk).'],
 ['WEC13','Define a natural monopoly.','A market where one firm can supply the whole market at lower average cost than two or more firms could.'],
 ['WEC13','What does a 14-mark data question need?','Knowledge, application to the extract, developed analysis, and evaluation of the specific points you made.'],
 ['WEC14','Define globalisation.','The growing integration and interdependence of the world’s economies through trade, capital, labour and technology.'],
 ['WEC14','Define comparative advantage.','A country can produce a good at a lower opportunity cost than another country.'],
 ['WEC14','Define the current account of the balance of payments.','The record of trade in goods and services, primary income and secondary income (transfers) with the rest of the world.'],
 ['WEC14','Absolute vs relative poverty?','Absolute: income below what is needed for basic needs. Relative: income well below the average in that society (e.g. below 60% of median).'],
 ['WEC14','What does the Gini coefficient measure?','Income inequality, from 0 (perfect equality) to 1 (one person has all income).'],
 ['WEC14','Using extracts in Unit 4: what works?','Use short, relevant evidence from the extract in your own words; copied sentences don’t reach the top levels.'],
 /* ---------- Geography ---------- */
 ['WGE01','“Describe” a Figure: what is needed?','Say what the data shows: trends, highs and lows, anomalies, with numbers and units quoted from the Figure.'],
 ['WGE01','“Explain” vs “describe”?','Explain gives reasons why; describe only says what. Explanations need linked causes, not a list.'],
 ['WGE01','“Compare”: what does it mean?','Point out similarities and differences side by side, using comparative words (whereas, more than, both).'],
 ['WGE01','Define a hazard.','A natural event that threatens people’s lives, property or livelihoods.'],
 ['WGE01','Disaster risk equation (in words)?','Risk = (hazard × vulnerability) ÷ capacity to cope.'],
 ['WGE01','Define vulnerability.','How exposed and unprotected a population is to a hazard (influenced by poverty, governance and preparedness).'],
 ['WGE01','Define globalisation (geography).','Increasing connections between places through trade, flows of capital, people and information, and TNCs.'],
 ['WGE01','Essay (Section B): what supports a top-level answer?','Named, located examples and data, a clear argument linked to the question, and a conclusion that judges.'],
 ['WGE02','“Identify”: how much do you write?','Just name the required number of points; no explanation needed.'],
 ['WGE02','Define coastal erosion processes (four).','Hydraulic action, abrasion (corrasion), attrition and solution (corrosion).'],
 ['WGE02','Define mass movement at the coast.','The downslope movement of material under gravity (e.g. slumping, rockfalls, landslides).'],
 ['WGE02','Primary vs secondary data?','Primary: collected yourself in the field. Secondary: collected by others (census, maps, reports).'],
 ['WGE02','Define regeneration.','Long-term improvement of an area’s economy, environment and social conditions.'],
 ['WGE02','Define rebranding.','Changing a place’s image, often by redeveloping it, to attract investment, visitors or residents.'],
 ['WGE02','Fieldwork questions: what earns marks?','Specific details from your own investigation: aim, sampling, method, results, and how you would improve it.'],
 ['WGE03','“Assess” or “evaluate” in a 15- or 20-mark essay?','Weigh up factors and arguments using evidence, then reach a supported judgement.'],
 ['WGE03','Define biodiversity.','The variety of life in an area: genetic, species and ecosystem diversity.'],
 ['WGE03','Define a biodiversity hotspot.','A region with very high numbers of endemic species that is under significant threat.'],
 ['WGE03','Define energy security.','Having reliable, affordable and sustainable access to enough energy.'],
 ['WGE03','Define water stress.','When the demand for water exceeds the available supply (below about 1,700 m³ per person per year).'],
 ['WGE03','Define a superpower.','A country with dominant global influence through economic, military, political and cultural power.'],
 ['WGE03','How should a case study be used in an essay?','Selectively: only the facts that support your argument for this question.'],
 ['WGE04','Structure of a Unit 4 report?','Introduction (focus on the question’s contention), research methods and sources, analysis, conclusion and evaluation of your research.'],
 ['WGE04','Why reference sources in Unit 4?','It credits your research and is rewarded: name the source, author or organisation, and the date.'],
 ['WGE04','Research vs analysis?','Research is what you found; analysis explains what it means for the question.'],
 /* ---------- Psychology ---------- */
 ['WPS01','“Describe” vs “explain” in short questions?','Describe: say what something is or does. Explain: give the reason, linked to the question.'],
 ['WPS01','Agency theory (Milgram): key idea?','People obey authority by entering an agentic state, seeing themselves as acting for someone else and so not responsible.'],
 ['WPS01','Social identity theory: three stages?','Social categorisation, social identification, social comparison (leading to in-group favouritism).'],
 ['WPS01','Multi-store model: three stores?','Sensory register, short-term memory, long-term memory, linked by attention and rehearsal.'],
 ['WPS01','Answering about your practical investigation?','Give specific details of your own study (aim, sample, procedure, results), not a generic description.'],
 ['WPS01','Strength or weakness questions: what earns the extra mark?','Justify it: explain why it is a strength or weakness, using the study or scenario.'],
 ['WPS01','Define a confounding variable.','A variable other than the IV that changes alongside it and affects the DV.'],
 ['WPS01','Define standardised procedure.','Every participant is treated in exactly the same way, so the study can be replicated.'],
 ['WPS02','Scenario (AO2) questions: how do you get the marks?','Use specific details from the scenario in every point.'],
 ['WPS02','Classical conditioning in one line?','Learning by association: a neutral stimulus paired with an unconditioned stimulus comes to trigger the response.'],
 ['WPS02','Operant conditioning in one line?','Learning from consequences: reinforcement increases behaviour, punishment decreases it.'],
 ['WPS02','Social learning theory: four processes?','Attention, retention, reproduction, motivation (from observing a model).'],
 ['WPS02','Improvement questions: what is creditworthy?','Explain how the change makes the study better, not just what was wrong.'],
 ['WPS02','Define a neurotransmitter.','A chemical messenger released across a synapse to pass a signal to the next neuron.'],
 ['WPS02','Define correlation.','A relationship between two co-variables, positive or negative, which doesn’t show cause.'],
 ['WPS03','Generic answers in scenario questions?','They score 0. Every point must link concept, study or theory to the scenario.'],
 ['WPS03','“Compare” in Psychology?','Make a two-sided point: how two things are similar or different, not two separate descriptions.'],
 ['WPS03','Define attachment.','A strong, lasting emotional bond between two people, typically infant and caregiver.'],
 ['WPS03','Primary vs secondary data?','Primary: gathered by the researcher for this study. Secondary: data gathered previously by others.'],
 ['WPS03','Improvement vs alternative method?','An improvement changes the existing study; a different method entirely isn’t credited.'],
 ['WPS03','When do you reject the null hypothesis?','When the calculated value passes the critical value at $p \\le 0.05$ (check the test’s direction rule).'],
 ['WPS04','Define a mental disorder (criteria to know).','Statistical infrequency, deviation from social norms, personal distress and dysfunctional behaviour (the 4 Ds).'],
 ['WPS04','Reliability vs validity of diagnosis?','Reliability: different clinicians give the same diagnosis. Validity: the diagnosis measures what it claims to.'],
 ['WPS04','AO3 in extended responses: what does it need?','Balanced evaluation with exemplified points, leading to a judgement or conclusion.'],
 ['WPS04','Key-question essay: common mistake?','Repeating the scenario. Apply psychological concepts and studies to explain it instead.'],
 ['WPS04','Should you use bullet points in extended answers?','No. Write in full, linked sentences to reach the higher levels.'],
 /* ---------- History ---------- */
 ['WHI01','How should a Section A essay be structured?','A focused introduction, analytical paragraphs each judging a factor against the question, and a conclusion with criteria-based judgement.'],
 ['WHI01','What makes a judgement “supported”?','Criteria: explain why one factor was more significant (e.g. scale, duration, impact on outcome).'],
 ['WHI01','Narrative vs analysis?','Narrative retells events; analysis argues how events answer the question.'],
 ['WHI01','Section B: comparing two interpretations?','Identify each historian’s argument, test both with your own knowledge, then judge which is more convincing.'],
 ['WHI01','Why stick to the dates in the question?','Marks only go to material inside the period asked; evidence outside it is irrelevant.'],
 ['WHI02','Source value question: what is an inference?','A point you deduce from the source that it doesn’t state directly, about the enquiry.'],
 ['WHI02','Nature, origin, purpose (NOP): how to use it?','Explain how the author, audience and purpose affect the source’s value for this enquiry, not stock comments about the source type.'],
 ['WHI02','Weight of a source: how to judge it?','Consider the author’s audience and aims, check claims against your own knowledge, and reach a judgement on how much it can be trusted for the enquiry.'],
 ['WHI02','In a value question, should you discuss limitations?','No: focus on what the source is valuable for.'],
 ['WHI03','Using two sources “together”?','Cross-reference them: compare their content and provenance to answer the enquiry, rather than treating each separately.'],
 ['WHI03','A thematic essay across a long period needs?','Change and continuity across the whole period, with precise examples from different points in time.'],
 ['WHI03','How long should your introduction be?','Short: set out your argument and criteria, then get into analysis.'],
 ['WHI04','Extracts (Section A): how do you treat them?','As historians’ interpretations: analyse their arguments by name; don’t evaluate provenance.'],
 ['WHI04','Section A judgement?','An overall view on the question’s claim, using both extracts and your own knowledge, not just a summary of each extract.'],
 ['WHI04','Section B essay success criteria?','Sustained analysis, precise evidence across the period, and a reasoned judgement.'],
 /* ---------- Computer Science ---------- */
 ['WCP01','Define an algorithm.','A precise sequence of steps that solves a problem.'],
 ['WCP01','Define abstraction.','Removing unnecessary detail to focus on what matters for solving the problem.'],
 ['WCP01','Define decomposition.','Breaking a problem down into smaller, more manageable sub-problems.'],
 ['WCP01','Lossy vs lossless compression?','Lossy permanently removes data to shrink files; lossless shrinks them so the original can be rebuilt exactly.'],
 ['WCP01','Symmetric vs asymmetric encryption?','Symmetric uses one shared key; asymmetric uses a public key to encrypt and a private key to decrypt.'],
 ['WCP02','Linear vs binary search?','Linear checks each item in turn (any list); binary halves a sorted list each step (much faster on large lists).'],
 ['WCP02','Define a subprogram’s parameter.','A value passed into a function or procedure when it is called.'],
 ['WCP02','Why test with normal, boundary and erroneous data?','To check the program handles typical input, the edges of valid ranges, and invalid input correctly.'],
 ['WCP03','Define a protocol.','A set of rules for how devices communicate over a network.'],
 ['WCP03','Stack vs queue?','A stack is last in, first out (LIFO); a queue is first in, first out (FIFO).'],
 ['WCP04','Define recursion.','A function that calls itself, with a base case to stop it.'],
 ['WCP04','Object-oriented programming: encapsulation?','Keeping an object’s data and methods together, and hiding the data so it can only be changed through methods.'],
 /* ---------- Mathematics and Further Mathematics: formulae to memorise (not in the formula booklet), methods and wording ---------- */
 ["WMA11", "Quadratic formula (not in the formula booklet)", "$x=\\frac{-b\\pm\\sqrt{b^{2}-4ac}}{2a}$ for $ax^{2}+bx+c=0$."],
 ["WMA11", "What does the discriminant $b^{2}-4ac$ tell you?", "$b^{2}-4ac>0$: two distinct real roots. $b^{2}-4ac=0$: one repeated (equal) root. $b^{2}-4ac<0$: no real roots."],
 ["WMA11", "Complete the square: $x^{2}+bx+c$", "$\\left(x+\\frac{b}{2}\\right)^{2}-\\frac{b^{2}}{4}+c$. The turning point is at $\\left(-\\frac{b}{2},\\ c-\\frac{b^{2}}{4}\\right)$."],
 ["WMA11", "How do you rationalise $\\frac{1}{\\sqrt{a}+\\sqrt{b}}$?", "Multiply top and bottom by $\\sqrt{a}-\\sqrt{b}$ to get $\\frac{\\sqrt{a}-\\sqrt{b}}{a-b}$."],
 ["WMA11", "Index laws for negative and fractional powers", "$a^{-n}=\\frac{1}{a^{n}}$, $a^{\\frac{1}{n}}=\\sqrt[n]{a}$, and $a^{\\frac{m}{n}}=\\left(a^{\\frac{1}{n}}\\right)^{m}$."],
 ["WMA11", "Equation of a straight line through $(x_{1},y_{1})$ with gradient $m$", "$y-y_{1}=m(x-x_{1})$."],
 ["WMA11", "Gradients of perpendicular lines", "$m_{1}\\times m_{2}=-1$, so the perpendicular gradient is $-\\frac{1}{m}$."],
 ["WMA11", "Sine rule (not in the formula booklet)", "$\\frac{a}{\\sin A}=\\frac{b}{\\sin B}=\\frac{c}{\\sin C}$. Only the cosine rule is given."],
 ["WMA11", "Area of a triangle using two sides and the included angle", "$\\text{Area}=\\frac{1}{2}ab\\sin C$."],
 ["WMA11", "Arc length and sector area (angle in radians)", "Arc length $s=r\\theta$. Sector area $A=\\frac{1}{2}r^{2}\\theta$."],
 ["WMA11", "Sine rule for an angle: why might there be two answers?", "$\\sin\\theta=\\sin(180^{\\circ}-\\theta)$, so if the obtuse angle $180^{\\circ}-\\theta$ also fits the triangle, both are possible (the ambiguous case)."],
 ["WMA11", "Translations: $y=f(x+a)$ and $y=f(x)+a$", "$y=f(x+a)$: move $a$ units to the left. $y=f(x)+a$: move $a$ units up."],
 ["WMA11", "Stretches: $y=af(x)$ and $y=f(ax)$", "$y=af(x)$: vertical stretch, scale factor $a$. $y=f(ax)$: horizontal stretch, scale factor $\\frac{1}{a}$."],
 ["WMA11", "Differentiate and integrate $x^{n}$", "$\\frac{d}{dx}\\left(x^{n}\\right)=nx^{n-1}$. $\\int x^{n}\\,dx=\\frac{x^{n+1}}{n+1}+c$ for $n\\neq-1$."],
 ["WMA11", "How do you find the equation of the normal to a curve at $x=a$?", "Find the gradient of the tangent $m=f^{\\prime}(a)$; the normal has gradient $-\\frac{1}{m}$; then use $y-y_{1}=m(x-x_{1})$ through $(a,f(a))$."],
 ["WMA11", "A line is a tangent to a curve. What condition do you use?", "Substitute the line into the curve to get a quadratic; it touches at one point, so the discriminant $b^{2}-4ac=0$."],
 ["WMA11", "How should the answer to a quadratic inequality be written?", "Find the critical values, sketch, then give the region, e.g. $x<1$ or $x>4$ (two separate parts), or $1<x<4$ (one interval)."],
 ["WMA12", "Factor theorem", "If $f(a)=0$ then $(x-a)$ is a factor of $f(x)$. If $f\\left(\\frac{b}{a}\\right)=0$ then $(ax-b)$ is a factor."],
 ["WMA12", "Remainder theorem", "When $f(x)$ is divided by $(x-a)$ the remainder is $f(a)$; when divided by $(ax-b)$ it is $f\\left(\\frac{b}{a}\\right)$."],
 ["WMA12", "Equation of a circle with centre $(a,b)$ and radius $r$", "$(x-a)^{2}+(y-b)^{2}=r^{2}$."],
 ["WMA12", "Three circle facts used in coordinate geometry", "A tangent is perpendicular to the radius at that point. The angle in a semicircle is $90^{\\circ}$. The perpendicular from the centre to a chord bisects the chord."],
 ["WMA12", "Laws of logarithms", "$\\log_{a}x+\\log_{a}y=\\log_{a}(xy)$, $\\log_{a}x-\\log_{a}y=\\log_{a}\\left(\\frac{x}{y}\\right)$, $k\\log_{a}x=\\log_{a}\\left(x^{k}\\right)$."],
 ["WMA12", "How do you solve $a^{x}=b$?", "Take logs of both sides: $x\\log a=\\log b$, so $x=\\frac{\\log b}{\\log a}$. Also $\\log_{a}a=1$ and $\\log_{a}1=0$."],
 ["WMA12", "Two trigonometric identities you must know (not in the booklet)", "$\\tan\\theta=\\frac{\\sin\\theta}{\\cos\\theta}$ and $\\sin^{2}\\theta+\\cos^{2}\\theta=1$."],
 ["WMA12", "Solving a trig equation in $0^{\\circ}\\le\\theta<360^{\\circ}$: where is the second solution?", "If the calculator gives $\\alpha$: $\\sin\\theta$: $180^{\\circ}-\\alpha$. $\\cos\\theta$: $360^{\\circ}-\\alpha$. $\\tan\\theta$: $\\alpha+180^{\\circ}$. Then add or subtract $360^{\\circ}$ to stay in range."],
 ["WMA12", "Stationary points: how do you find them and their nature?", "Solve $\\frac{dy}{dx}=0$. If $\\frac{d^{2}y}{dx^{2}}>0$ it is a minimum; if $\\frac{d^{2}y}{dx^{2}}<0$ it is a maximum."],
 ["WMA12", "Increasing and decreasing functions", "Increasing where $f^{\\prime}(x)>0$; decreasing where $f^{\\prime}(x)<0$."],
 ["WMA12", "Area between a curve and the $x$-axis when part is below the axis", "Integrate each part separately. A region below the axis gives a negative value: take its size, then add the areas."],
 ["WMA12", "Trapezium rule: over- or underestimate?", "Overestimate if the curve is convex (bends upwards, like $y=x^{2}$); underestimate if it is concave (bends downwards). Explain it using the shape of the curve."],
 ["WMA12", "Disproof by counter-example: what do you need?", "One specific example where the statement is false, with the working that shows it fails."],
 ["WMA12", "Proof by exhaustion", "Split into a finite number of cases that cover every possibility, and prove the statement in each case."],
 ["WMA12", "Sequences defined by $u_{n+1}=f(u_{n})$: increasing and periodic", "Increasing: $u_{n+1}>u_{n}$ for all $n$. Periodic: the terms repeat in a cycle; the period is the number of terms in one cycle."],
 ["WMA13", "Double-angle formulae (not in the formula booklet)", "$\\sin2A=2\\sin A\\cos A$; $\\cos2A=\\cos^{2}A-\\sin^{2}A=2\\cos^{2}A-1=1-2\\sin^{2}A$; $\\tan2A=\\frac{2\\tan A}{1-\\tan^{2}A}$."],
 ["WMA13", "Identities linking $\\sec$, $\\operatorname{cosec}$ and $\\cot$", "$1+\\tan^{2}\\theta=\\sec^{2}\\theta$ and $1+\\cot^{2}\\theta=\\operatorname{cosec}^{2}\\theta$."],
 ["WMA13", "Definitions of $\\sec$, $\\operatorname{cosec}$ and $\\cot$", "$\\sec\\theta=\\frac{1}{\\cos\\theta}$, $\\operatorname{cosec}\\theta=\\frac{1}{\\sin\\theta}$, $\\cot\\theta=\\frac{1}{\\tan\\theta}=\\frac{\\cos\\theta}{\\sin\\theta}$."],
 ["WMA13", "Write $a\\cos\\theta+b\\sin\\theta$ in the form $R\\cos(\\theta-\\alpha)$", "Expand: $R\\cos\\alpha=a$ and $R\\sin\\alpha=b$. So $R=\\sqrt{a^{2}+b^{2}}$ and $\\tan\\alpha=\\frac{b}{a}$."],
 ["WMA13", "Ranges of the inverse trig functions", "$\\arcsin x$: $-\\frac{\\pi}{2}\\le y\\le\\frac{\\pi}{2}$. $\\arccos x$: $0\\le y\\le\\pi$. $\\arctan x$: $-\\frac{\\pi}{2}<y<\\frac{\\pi}{2}$."],
 ["WMA13", "Derivatives of $e^{kx}$, $\\ln x$, $\\sin kx$, $\\cos kx$ (not in the booklet)", "$ke^{kx}$, $\\frac{1}{x}$, $k\\cos kx$, $-k\\sin kx$."],
 ["WMA13", "Chain rule and product rule", "Chain: $\\frac{dy}{dx}=\\frac{dy}{du}\\times\\frac{du}{dx}$. Product: $\\frac{d}{dx}(uv)=u\\frac{dv}{dx}+v\\frac{du}{dx}$. (Only the quotient rule is in the booklet.)"],
 ["WMA13", "How do you find $\\frac{dy}{dx}$ when $x$ is given in terms of $y$?", "Find $\\frac{dx}{dy}$, then $\\frac{dy}{dx}=\\frac{1}{\\frac{dx}{dy}}$."],
 ["WMA13", "Integrals of $e^{kx}$, $\\frac{1}{x}$, $\\sin kx$, $\\cos kx$", "$\\frac{1}{k}e^{kx}+c$, $\\ln|x|+c$, $-\\frac{1}{k}\\cos kx+c$, $\\frac{1}{k}\\sin kx+c$."],
 ["WMA13", "What does $fg(x)$ mean?", "$f(g(x))$: apply $g$ first, then $f$."],
 ["WMA13", "Inverse function $f^{-1}$: graph, domain and range", "Its graph is the reflection of $y=f(x)$ in $y=x$. Domain of $f^{-1}$ = range of $f$; range of $f^{-1}$ = domain of $f$. It exists only if $f$ is one-to-one."],
 ["WMA13", "Sketching $y=|f(x)|$ and $y=f(|x|)$", "$y=|f(x)|$: reflect any part below the $x$-axis up above it. $y=f(|x|)$: keep the part for $x\\ge0$ and reflect it in the $y$-axis."],
 ["WMA13", "Showing a root lies in an interval: what must you write?", "Calculate $f(a)$ and $f(b)$, state there is a change of sign and that $f$ is continuous on $[a,b]$, so there is a root between $a$ and $b$."],
 ["WMA13", "$e$ and $\\ln$ undo each other", "$e^{\\ln x}=x$ for $x>0$, and $\\ln\\left(e^{x}\\right)=x$."],
 ["WMA13", "Exponential model $y=Ae^{-kt}$: what is $A$?", "The initial value (the value when $t=0$). With $k>0$ the model shows decay towards 0."],
 ["WMA14", "Partial fractions: the forms to use", "$\\frac{px+q}{(x+a)(x+b)}=\\frac{A}{x+a}+\\frac{B}{x+b}$. Repeated factor: $\\frac{px^{2}+qx+r}{(x+a)(x+b)^{2}}=\\frac{A}{x+a}+\\frac{B}{x+b}+\\frac{C}{(x+b)^{2}}$."],
 ["WMA14", "Parametric differentiation", "$\\frac{dy}{dx}=\\frac{\\frac{dy}{dt}}{\\frac{dx}{dt}}$."],
 ["WMA14", "Implicit differentiation of $y^{n}$ and $xy$", "$\\frac{d}{dx}\\left(y^{n}\\right)=ny^{n-1}\\frac{dy}{dx}$ and $\\frac{d}{dx}(xy)=x\\frac{dy}{dx}+y$."],
 ["WMA14", "Volume of revolution about the $x$-axis (not in the booklet)", "$V=\\pi\\int_{a}^{b}y^{2}\\,dx$."],
 ["WMA14", "Integral of $\\frac{f^{\\prime}(x)}{f(x)}$", "$\\int\\frac{f^{\\prime}(x)}{f(x)}\\,dx=\\ln|f(x)|+c$."],
 ["WMA14", "Integrating $\\sin^{2}x$ and $\\cos^{2}x$", "Use $\\sin^{2}x=\\frac{1}{2}(1-\\cos2x)$ and $\\cos^{2}x=\\frac{1}{2}(1+\\cos2x)$, then integrate."],
 ["WMA14", "Integration by substitution: what must you change?", "Replace $dx$ using $\\frac{du}{dx}$, write everything in $u$, and change the limits to $u$-values (or substitute back before using the $x$ limits)."],
 ["WMA14", "Solving a separable differential equation $\\frac{dy}{dx}=f(x)g(y)$", "$\\int\\frac{1}{g(y)}\\,dy=\\int f(x)\\,dx$. Add $+c$, then use the given condition to find $c$."],
 ["WMA14", "Validity of the binomial expansion of $(a+bx)^{n}$ for non-integer $n$", "Valid for $\\left|\\frac{bx}{a}\\right|<1$, that is $|x|<\\frac{|a|}{|b|}$. Take out $a^{n}$ first: $(a+bx)^{n}=a^{n}\\left(1+\\frac{b}{a}x\\right)^{n}$."],
 ["WMA14", "Scalar product and the angle between two vectors", "$\\mathbf{a}\\cdot\\mathbf{b}=a_{1}b_{1}+a_{2}b_{2}+a_{3}b_{3}=|\\mathbf{a}||\\mathbf{b}|\\cos\\theta$."],
 ["WMA14", "When are two vectors perpendicular?", "When $\\mathbf{a}\\cdot\\mathbf{b}=0$."],
 ["WMA14", "Vector equation of a line", "$\\mathbf{r}=\\mathbf{a}+\\lambda\\mathbf{b}$: $\\mathbf{a}$ is the position vector of a point on the line, $\\mathbf{b}$ is its direction."],
 ["WMA14", "Two lines in 3D: what does skew mean?", "They are not parallel and do not intersect."],
 ["WMA14", "Magnitude of a vector", "$|\\mathbf{a}|=\\sqrt{a_{1}^{2}+a_{2}^{2}+a_{3}^{2}}$. A unit vector in the same direction is $\\frac{\\mathbf{a}}{|\\mathbf{a}|}$."],
 ["WMA14", "Proof by contradiction: how does it start and end?", "Assume the opposite of the statement, show this leads to something impossible, and conclude the assumption was false, so the statement is true."],
 ["WMA14", "Connected rates of change", "Use the chain rule, e.g. $\\frac{dV}{dt}=\\frac{dV}{dr}\\times\\frac{dr}{dt}$."],
 ["WFM01", "Sum and product of the roots of $ax^{2}+bx+c=0$", "$\\alpha+\\beta=-\\frac{b}{a}$ and $\\alpha\\beta=\\frac{c}{a}$."],
 ["WFM01", "Write $\\alpha^{2}+\\beta^{2}$ and $\\alpha^{3}+\\beta^{3}$ using $\\alpha+\\beta$ and $\\alpha\\beta$", "$\\alpha^{2}+\\beta^{2}=(\\alpha+\\beta)^{2}-2\\alpha\\beta$ and $\\alpha^{3}+\\beta^{3}=(\\alpha+\\beta)^{3}-3\\alpha\\beta(\\alpha+\\beta)$."],
 ["WFM01", "Modulus and argument of $z=a+bi$", "$|z|=\\sqrt{a^{2}+b^{2}}$. $\\arg z$ is the angle from the positive real axis; use $\\tan^{-1}\\left(\\frac{b}{a}\\right)$ and adjust for the quadrant, giving $-\\pi<\\arg z\\le\\pi$."],
 ["WFM01", "Complex roots of a polynomial with real coefficients", "They come in conjugate pairs: if $a+bi$ is a root, so is $a-bi$."],
 ["WFM01", "How do you divide by a complex number?", "Multiply top and bottom by the conjugate of the denominator. Useful fact: $zz^{*}=|z|^{2}$."],
 ["WFM01", "Sum of the first $n$ integers (with $\\sum r^{2}$ and $\\sum r^{3}$ from the booklet)", "$\\sum_{r=1}^{n}r=\\frac{1}{2}n(n+1)$, and $\\sum_{r=1}^{n}1=n$."],
 ["WFM01", "Proof by induction: the closing statement", "True for $n=1$; if true for $n=k$ then true for $n=k+1$; so by mathematical induction it is true for all $n\\in\\mathbb{Z}^{+}$."],
 ["WFM01", "Inverse of $\\begin{pmatrix}a&b\\\\c&d\\end{pmatrix}$", "$\\dfrac{1}{ad-bc}\\begin{pmatrix}d&-b\\\\-c&a\\end{pmatrix}$: swap $a$ and $d$, change the signs of $b$ and $c$, divide by the determinant. It exists only when $ad-bc\\neq0$."],
 ["WFM01", "What is a singular matrix?", "One whose determinant is 0, so it has no inverse."],
 ["WFM01", "What does the determinant of a transformation matrix tell you?", "$|\\det\\mathbf{M}|$ is the area scale factor. A negative determinant means the shape is also reflected (orientation reversed)."],
 ["WFM01", "Order of transformations: what does $\\mathbf{AB}$ do?", "$\\mathbf{B}$ first, then $\\mathbf{A}$. Also $(\\mathbf{AB})^{-1}=\\mathbf{B}^{-1}\\mathbf{A}^{-1}$."],
 ["WFM01", "Linear interpolation for a root between $a$ and $b$", "Use similar triangles: $\\alpha\\approx a+\\frac{|f(a)|}{|f(a)|+|f(b)|}(b-a)$, where $f(a)$ and $f(b)$ have opposite signs."],
 ["WFM01", "Interval bisection: one step", "Find the midpoint $m$ of $[a,b]$, evaluate $f(m)$, and keep the half where the sign changes."],
 ["WFM02", "Method of differences", "Write each term as $f(r)-f(r+1)$. Most terms cancel, so $\\sum_{r=1}^{n}\\left[f(r)-f(r+1)\\right]=f(1)-f(n+1)$."],
 ["WFM02", "Inequality with an algebraic fraction: what must you not do?", "Do not multiply by an expression that could be negative. Multiply by its square instead, or move everything to one side and use critical values."],
 ["WFM02", "Integrating factor for $\\frac{dy}{dx}+Py=Q$", "$\\text{IF}=e^{\\int P\\,dx}$. Then $y\\times\\text{IF}=\\int Q\\times\\text{IF}\\,dx$."],
 ["WFM02", "Complementary function from the auxiliary equation $am^{2}+bm+c=0$", "Distinct real roots: $Ae^{m_{1}x}+Be^{m_{2}x}$. Repeated root: $(A+Bx)e^{mx}$. Complex roots $p\\pm qi$: $e^{px}(A\\cos qx+B\\sin qx)$."],
 ["WFM02", "General solution of a second-order differential equation", "General solution = complementary function + particular integral."],
 ["WFM02", "Trial forms for the particular integral", "Polynomial of degree $n$: general polynomial of degree $n$. $ke^{px}$: $\\lambda e^{px}$ (try $\\lambda xe^{px}$ if $p$ is a root). $k\\cos px$ or $k\\sin px$: $\\lambda\\cos px+\\mu\\sin px$."],
 ["WFM02", "Loci: $|z-a|=r$ and $|z-a|=|z-b|$", "$|z-a|=r$: circle, centre $a$, radius $r$. $|z-a|=|z-b|$: perpendicular bisector of the line joining $a$ and $b$."],
 ["WFM02", "Locus $\\arg(z-a)=\\theta$", "A half-line from the point $a$ at angle $\\theta$ to the positive real direction, not including $a$ itself."],
 ["WFM02", "If $z=\\cos\\theta+i\\sin\\theta$, what are $z^{n}+\\frac{1}{z^{n}}$ and $z^{n}-\\frac{1}{z^{n}}$?", "$z^{n}+\\frac{1}{z^{n}}=2\\cos n\\theta$ and $z^{n}-\\frac{1}{z^{n}}=2i\\sin n\\theta$."],
 ["WFM02", "Polar and Cartesian coordinates", "$x=r\\cos\\theta$, $y=r\\sin\\theta$, $r^{2}=x^{2}+y^{2}$."],
 ["WFM02", "Polar curve: tangents parallel and perpendicular to the initial line", "Parallel: $\\frac{d}{d\\theta}(r\\sin\\theta)=0$. Perpendicular: $\\frac{d}{d\\theta}(r\\cos\\theta)=0$."],
 ["WFM03", "Definitions of $\\sinh x$, $\\cosh x$, $\\tanh x$", "$\\sinh x=\\frac{e^{x}-e^{-x}}{2}$, $\\cosh x=\\frac{e^{x}+e^{-x}}{2}$, $\\tanh x=\\frac{\\sinh x}{\\cosh x}=\\frac{e^{2x}-1}{e^{2x}+1}$."],
 ["WFM03", "Osborn’s rule", "To turn a trig identity into a hyperbolic one, replace $\\cos$ with $\\cosh$ and $\\sin$ with $\\sinh$, and change the sign of any product of two sines (including $\\tan^{2}$)."],
 ["WFM03", "Reduction formula: the usual method", "Write $I_{n}$, integrate by parts (often after splitting off a power), and rearrange to get $I_{n}$ in terms of $I_{n-1}$ or $I_{n-2}$."],
 ["WFM03", "Determinant of $\\begin{pmatrix}a&b&c\\\\d&e&f\\\\g&h&i\\end{pmatrix}$", "$a(ei-fh)-b(di-fg)+c(dh-eg)$."],
 ["WFM03", "Inverse of a $3\\times3$ matrix", "$\\mathbf{M}^{-1}=\\frac{1}{\\det\\mathbf{M}}\\times$ (the transpose of the matrix of cofactors), for $\\det\\mathbf{M}\\neq0$."],
 ["WFM03", "Eigenvalues and eigenvectors", "Eigenvalues: solve $\\det(\\mathbf{M}-\\lambda\\mathbf{I})=0$. Eigenvector for $\\lambda$: a non-zero solution of $(\\mathbf{M}-\\lambda\\mathbf{I})\\mathbf{x}=\\mathbf{0}$."],
 ["WFM03", "Diagonalising a symmetric matrix", "Put normalised eigenvectors as the columns of $\\mathbf{P}$ (orthogonal, so $\\mathbf{P}^{-1}=\\mathbf{P}^{T}$). Then $\\mathbf{P}^{T}\\mathbf{MP}=\\mathbf{D}$, with the eigenvalues on the diagonal of $\\mathbf{D}$."],
 ["WFM03", "Angle between a line and a plane", "$\\sin\\theta=\\frac{|\\mathbf{b}\\cdot\\mathbf{n}|}{|\\mathbf{b}||\\mathbf{n}|}$, where $\\mathbf{b}$ is the line direction and $\\mathbf{n}$ the plane normal. (Sine, because $\\mathbf{n}$ is perpendicular to the plane.)"],
 ["WFM03", "Angle between two planes", "The angle between their normals: $\\cos\\theta=\\frac{|\\mathbf{n}_{1}\\cdot\\mathbf{n}_{2}|}{|\\mathbf{n}_{1}||\\mathbf{n}_{2}|}$."],
 ["WFM03", "Direction of the line where two planes meet", "$\\mathbf{n}_{1}\\times\\mathbf{n}_{2}$: it is perpendicular to both normals."],
 ["WFM03", "Shortest distance between skew lines $\\mathbf{r}=\\mathbf{a}+\\lambda\\mathbf{b}$ and $\\mathbf{r}=\\mathbf{c}+\\mu\\mathbf{d}$", "$\\frac{|(\\mathbf{a}-\\mathbf{c})\\cdot(\\mathbf{b}\\times\\mathbf{d})|}{|\\mathbf{b}\\times\\mathbf{d}|}$."],
 ["WME01", "The suvat equations (no formulae are given for M1)", "$v=u+at$, $s=ut+\\frac{1}{2}at^{2}$, $s=\\frac{1}{2}(u+v)t$, $v^{2}=u^{2}+2as$, $s=vt-\\frac{1}{2}at^{2}$. Constant acceleration only."],
 ["WME01", "Speed–time and velocity–time graphs", "Gradient = acceleration. Area under the graph = distance travelled (or displacement for velocity–time)."],
 ["WME01", "Friction", "$F\\le\\mu R$. When the object is moving, or on the point of moving (limiting equilibrium), $F=\\mu R$."],
 ["WME01", "Newton’s second law and weight", "$F=ma$ (resultant force), and weight $W=mg$ with $g=9.8\\ \\text{m s}^{-2}$."],
 ["WME01", "Momentum and impulse", "Momentum $=mv$. Impulse $=$ change in momentum $=mv-mu$; for a constant force, impulse $=Ft$."],
 ["WME01", "Particle on a slope at angle $\\alpha$: components of the weight", "$mg\\sin\\alpha$ down the slope and $mg\\cos\\alpha$ perpendicular to it."],
 ["WME01", "Rigid body in equilibrium: the two conditions", "The resultant force is zero (resolve in two directions), and the sum of moments about any point is zero."],
 ["WME01", "A beam is on the point of tipping about a support. What do you use?", "The reaction at the other support is zero, so take moments about the support it tips about."],
 ["WME01", "Velocity as a vector: speed and position", "Speed $=|\\mathbf{v}|$. For constant velocity, $\\mathbf{r}=\\mathbf{r}_{0}+\\mathbf{v}t$."],
 ["WME02", "Variable acceleration: linking displacement, velocity and acceleration", "$v=\\frac{dx}{dt}$, $a=\\frac{dv}{dt}=\\frac{d^{2}x}{dt^{2}}$. Integrate to go back, using given values to find the constant."],
 ["WME02", "Projectile launched at speed $u$, angle $\\alpha$ above the horizontal", "Horizontally: $x=(u\\cos\\alpha)t$. Vertically: $y=(u\\sin\\alpha)t-\\frac{1}{2}gt^{2}$. At the highest point the vertical velocity is 0."],
 ["WME02", "Work done by a constant force", "$W=Fs$: force $\\times$ distance moved in the direction of the force. Work done against friction $=\\mu Rs$."],
 ["WME02", "Kinetic and gravitational potential energy", "$\\text{KE}=\\frac{1}{2}mv^{2}$ and $\\text{GPE}=mgh$."],
 ["WME02", "Power of a vehicle", "$P=Fv$, where $F$ is the driving force. At maximum (constant) speed the driving force equals the total resistance."],
 ["WME02", "Newton’s law of restitution", "Speed of separation $=e\\times$ speed of approach, with $0\\le e\\le1$. $e=1$: perfectly elastic. $e=0$: the particles move together after the impact."],
 ["WME02", "Particle hits a fixed smooth wall at speed $u$", "It rebounds at speed $eu$, in the opposite direction."],
 ["WME02", "Centre of mass of a composite body", "$\\bar{x}=\\frac{\\sum m_{i}x_{i}}{\\sum m_{i}}$ (and the same for $\\bar{y}$). For a uniform lamina, use areas in place of masses."],
 ["WME02", "A lamina is hung freely from a point. How does it hang?", "With its centre of mass vertically below the point of suspension."],
 ["WME03", "Hooke’s law for an elastic string or spring", "$T=\\frac{\\lambda x}{l}$, where $\\lambda$ is the modulus of elasticity, $x$ the extension and $l$ the natural length."],
 ["WME03", "Elastic potential energy", "$\\text{EPE}=\\frac{\\lambda x^{2}}{2l}$."],
 ["WME03", "Acceleration given as a function of displacement", "Use $a=v\\frac{dv}{dx}=\\frac{d}{dx}\\left(\\frac{1}{2}v^{2}\\right)$, then separate the variables and integrate."],
 ["WME03", "Definition of simple harmonic motion", "The acceleration is proportional to the displacement from a fixed point and directed towards that point: $\\ddot{x}=-\\omega^{2}x$."],
 ["WME03", "SHM: speed, maximum values and period (amplitude $a$)", "$v^{2}=\\omega^{2}\\left(a^{2}-x^{2}\\right)$. Maximum speed $a\\omega$ (at the centre). Maximum acceleration $a\\omega^{2}$ (at the ends). Period $\\frac{2\\pi}{\\omega}$."],
 ["WME03", "SHM: displacement as a function of time", "$x=a\\sin\\omega t$ if timing starts at the centre; $x=a\\cos\\omega t$ if timing starts at an end."],
 ["WME03", "Conical pendulum: the two equations", "With the string at angle $\\theta$ to the vertical, resolve vertically: $T\\cos\\theta=mg$. Horizontally (towards the centre): $T\\sin\\theta=mr\\omega^{2}$."],
 ["WME03", "Vertical circle: when does a particle on a string complete the circle?", "If the string stays taut: tension $T\\ge0$ at the top, which needs $v^{2}\\ge rg$ there."],
 ["WME03", "Vertical circle: when does a particle on a light rod complete the circle?", "If its speed at the top is greater than zero (a rod can push as well as pull)."],
 ["WME03", "Particle moving on the outside of a smooth sphere: when does it leave the surface?", "When the normal reaction becomes zero."],
 ["WST01", "Coding: if $y=\\frac{x-a}{b}$, how do you get back the mean and standard deviation of $x$?", "$\\bar{x}=a+b\\bar{y}$ and $\\sigma_{x}=b\\sigma_{y}$ (adding $a$ does not change the spread)."],
 ["WST01", "Variance from data", "$\\sigma^{2}=\\frac{\\sum x^{2}}{n}-\\bar{x}^{2}$ (for a frequency table, $\\frac{\\sum fx^{2}}{\\sum f}-\\bar{x}^{2}$)."],
 ["WST01", "Histograms", "Frequency density $=\\frac{\\text{frequency}}{\\text{class width}}$. The area of each bar is proportional to the frequency."],
 ["WST01", "Describing skew from the mean and median", "Positive skew: mean > median (or $Q_{3}-Q_{2}>Q_{2}-Q_{1}$). Negative skew: mean < median. Symmetric: roughly equal."],
 ["WST01", "Mean and variance of $aX+b$", "$E(aX+b)=aE(X)+b$ and $\\text{Var}(aX+b)=a^{2}\\text{Var}(X)$."],
 ["WST01", "Standardising a normal variable", "$Z=\\frac{X-\\mu}{\\sigma}$, where $Z\\sim N(0,1)$."],
 ["WST01", "Discrete probability distribution: the condition", "All the probabilities add up to 1: $\\sum P(X=x)=1$."],
 ["WST01", "Using a regression line: interpolation or extrapolation?", "Interpolation (within the data range) is reliable. Extrapolation (outside it) is unreliable because the relationship may not continue."],
 ["WST01", "Interpreting $b$ in the regression line $y=a+bx$", "In context: for each extra unit of $x$, $y$ increases by $b$ units on average."],
 ["WST02", "Normal approximation to the binomial $B(n,p)$", "When $n$ is large and $p$ is close to 0.5 (usually $np>5$ and $n(1-p)>5$): $N\\left(np,\\ np(1-p)\\right)$, with a continuity correction."],
 ["WST02", "Poisson approximation to the binomial $B(n,p)$", "When $n$ is large and $p$ is small: $Po(np)$."],
 ["WST02", "Normal approximation to the Poisson $Po(\\lambda)$", "When $\\lambda$ is large (usually $\\lambda>10$): $N(\\lambda,\\lambda)$, with a continuity correction."],
 ["WST02", "Continuity correction examples", "$P(X\\le7)\\approx P(Y<7.5)$; $P(X\\ge7)\\approx P(Y>6.5)$; $P(X=7)\\approx P(6.5<Y<7.5)$."],
 ["WST02", "Linking the pdf $f(x)$ and the cdf $F(x)$", "$F(x)=\\int_{-\\infty}^{x}f(t)\\,dt$ and $f(x)=F^{\\prime}(x)$. The median $m$ satisfies $F(m)=0.5$; the mode is where $f(x)$ is greatest."],
 ["WST02", "Actual significance level of a test", "The probability of the test statistic falling in the critical region when $H_{0}$ is true."],
 ["WST02", "Two-tailed test at significance level $\\alpha$", "Put $\\frac{\\alpha}{2}$ in each tail."],
 ["WST02", "Census or sample?", "A census uses every member of the population: accurate, but slow and costly, and impossible if testing destroys the items. A sample is quicker and cheaper but may not represent the population."],
 ["WST02", "Sampling frame and statistic", "Sampling frame: a list of the sampling units in the population. Statistic: a quantity calculated only from the sample, with no unknown parameters."],
 ["WST03", "$\\text{Var}(X_{1}+X_{2})$ or $\\text{Var}(2X)$: which is which?", "Two independent observations: $\\text{Var}(X_{1}+X_{2})=2\\sigma^{2}$. One observation doubled: $\\text{Var}(2X)=4\\sigma^{2}$."],
 ["WST03", "Stratified sampling vs quota sampling", "Both split the population into groups in proportion. Stratified chooses at random within each group; quota does not (the interviewer chooses), so it can be biased."],
 ["WST03", "Systematic sampling", "Choose every $k$th member from a list, starting at a randomly chosen point among the first $k$."],
 ["WST03", "Confidence interval for a mean ($\\sigma$ known, or $n$ large)", "$\\bar{x}\\pm z\\frac{\\sigma}{\\sqrt{n}}$; for 95%, $z=1.96$."],
 ["WST03", "What does a 95% confidence interval mean?", "If many such intervals were found from repeated samples, about 95% of them would contain the true mean $\\mu$."],
 ["WST03", "$\\chi^{2}$ tests: degrees of freedom", "Goodness of fit: $\\nu=k-1-p$, where $k$ is the number of classes after combining and $p$ the number of parameters estimated. Contingency table: $\\nu=(r-1)(c-1)$."],
 ["WST03", "$\\chi^{2}$ tests: small expected frequencies", "Combine classes so every expected frequency is at least 5."],
 ["WST03", "Spearman’s rank or the product moment correlation test?", "PMCC tests need the data to be from a bivariate normal distribution. Use Spearman’s when the data are ranks or the relationship is not linear (but consistently increasing or decreasing)."],
 ["WST03", "Hypotheses for a test of correlation", "$H_{0}:\\rho=0$ (no correlation). $H_{1}:\\rho>0$, $\\rho<0$ or $\\rho\\neq0$, depending on the question."]
];
function kpHash(t){ let h = 5381; for (let i = 0; i < t.length; i++) h = ((h << 5) + h + t.charCodeAt(i)) | 0; return (h >>> 0).toString(36); }
const KEY_CARDS = KEY_PHRASES_RAW.map(r => ({ id: 'kp-' + r[0] + '-' + kpHash(r[1]), u: r[0], f: r[1], b: r[2], kp: true }));
